pub enum tbpTrajectoryOffset {}

/// A trajectory, column-major: TIMES has one entry per sample, STATES six,
/// STATE_TRANSITION 36 (row-major 6x6) when it was propagated.
#[derive(Copy, Clone, PartialEq)]
pub struct tbpTrajectory<'a> {
    pub _tab: ::flatbuffers::Table<'a>,
}

impl<'a> ::flatbuffers::Follow<'a> for tbpTrajectory<'a> {
    type Inner = tbpTrajectory<'a>;

    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self { _tab: unsafe { ::flatbuffers::Table::new(buf, loc) } }
    }
}

impl<'a> tbpTrajectory<'a> {
    pub const VT_DIMENSIONAL: ::flatbuffers::VOffsetT = 4;
    pub const VT_FRAME: ::flatbuffers::VOffsetT = 6;
    pub const VT_EPOCH_MS: ::flatbuffers::VOffsetT = 8;
    pub const VT_TIMES: ::flatbuffers::VOffsetT = 10;
    pub const VT_STATES: ::flatbuffers::VOffsetT = 12;
    pub const VT_STATE_TRANSITION: ::flatbuffers::VOffsetT = 14;
    pub const VT_JACOBI: ::flatbuffers::VOffsetT = 16;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        tbpTrajectory { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args tbpTrajectoryArgs<'args>
    ) -> ::flatbuffers::WIPOffset<tbpTrajectory<'bldr>> {
        let mut builder = tbpTrajectoryBuilder::new(_fbb);
        builder.add_JACOBI(args.JACOBI);
        builder.add_EPOCH_MS(args.EPOCH_MS);
        if let Some(x) = args.STATE_TRANSITION { builder.add_STATE_TRANSITION(x); }
        if let Some(x) = args.STATES { builder.add_STATES(x); }
        if let Some(x) = args.TIMES { builder.add_TIMES(x); }
        if let Some(x) = args.FRAME { builder.add_FRAME(x); }
        builder.add_DIMENSIONAL(args.DIMENSIONAL);
        builder.finish()
    }

    pub fn unpack(&self) -> tbpTrajectoryT {
        let DIMENSIONAL = self.DIMENSIONAL();
        let FRAME = self.FRAME().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let EPOCH_MS = self.EPOCH_MS();
        let TIMES = self.TIMES().map(|x| {
            x.into_iter().collect()
        });
        let STATES = self.STATES().map(|x| {
            x.into_iter().collect()
        });
        let STATE_TRANSITION = self.STATE_TRANSITION().map(|x| {
            x.into_iter().collect()
        });
        let JACOBI = self.JACOBI();
        tbpTrajectoryT {
            DIMENSIONAL,
            FRAME,
            EPOCH_MS,
            TIMES,
            STATES,
            STATE_TRANSITION,
            JACOBI,
        }
    }

    /// True when TIMES and STATES are dimensional (s, km, km/s) in FRAME;
    /// false = non-dimensional synodic.
    #[inline]
    pub fn DIMENSIONAL(&self) -> bool {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<bool>(tbpTrajectory::VT_DIMENSIONAL, Some(false)).unwrap()}
    }

    /// Frame of a dimensional trajectory; empty for synodic.
    #[inline]
    pub fn FRAME(&self) -> Option<RFM<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<RFM>>(tbpTrajectory::VT_FRAME, None)}
    }

    /// Unix milliseconds of time 0 of a dimensional trajectory; 0 = relative.
    #[inline]
    pub fn EPOCH_MS(&self) -> i64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<i64>(tbpTrajectory::VT_EPOCH_MS, Some(0)).unwrap()}
    }

    #[inline]
    pub fn TIMES(&self) -> Option<::flatbuffers::Vector<'a, f64>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, f64>>>(tbpTrajectory::VT_TIMES, None)}
    }

    /// x, y, z, vx, vy, vz per sample.
    #[inline]
    pub fn STATES(&self) -> Option<::flatbuffers::Vector<'a, f64>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, f64>>>(tbpTrajectory::VT_STATES, None)}
    }

    /// State transition matrix from time 0, 36 values per sample; empty = not
    /// propagated.
    #[inline]
    pub fn STATE_TRANSITION(&self) -> Option<::flatbuffers::Vector<'a, f64>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, f64>>>(tbpTrajectory::VT_STATE_TRANSITION, None)}
    }

    /// Jacobi constant of the trajectory (conserved in the CR3BP).
    #[inline]
    pub fn JACOBI(&self) -> f64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<f64>(tbpTrajectory::VT_JACOBI, Some(0.0)).unwrap()}
    }
}

impl ::flatbuffers::Verifiable for tbpTrajectory<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<bool>("DIMENSIONAL", Self::VT_DIMENSIONAL, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<RFM>>("FRAME", Self::VT_FRAME, false)?
            .visit_field::<i64>("EPOCH_MS", Self::VT_EPOCH_MS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("TIMES", Self::VT_TIMES, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("STATES", Self::VT_STATES, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, f64>>>("STATE_TRANSITION", Self::VT_STATE_TRANSITION, false)?
            .visit_field::<f64>("JACOBI", Self::VT_JACOBI, false)?
            .finish();
        Ok(())
    }
}

