        let PERILUNE_ALTITUDE_KM = self.PERILUNE_ALTITUDE_KM();
        let APOLUNE_ALTITUDE_KM = self.APOLUNE_ALTITUDE_KM();
        let INITIAL_STATE = self.INITIAL_STATE().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let PERIOD = self.PERIOD();
        let PERIOD_S = self.PERIOD_S();
        let JACOBI = self.JACOBI();
        let CORRECTED = self.CORRECTED();
        let CONVERGED = self.CONVERGED();
        let ITERATIONS = self.ITERATIONS();
        let TOLERANCE = self.TOLERANCE();
        let MAX_ITERATIONS = self.MAX_ITERATIONS();
        let MONODROMY = self.MONODROMY().map(|x| {
            x.into_iter().collect()
        });
        let FLOQUET_REAL = self.FLOQUET_REAL().map(|x| {
            x.into_iter().collect()
        });
        let FLOQUET_IMAGINARY = self.FLOQUET_IMAGINARY().map(|x| {
            x.into_iter().collect()
        });
        let STABILITY_INDEX = self.STABILITY_INDEX();
        let STABLE = self.STABLE();
        let TRAJECTORY = self.TRAJECTORY().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        tbpPeriodicOrbitT {
            FAMILY,
            LIBRATION_POINT,
            AMPLITUDE,
            PERILUNE_ALTITUDE_KM,
            APOLUNE_ALTITUDE_KM,
            INITIAL_STATE,
            PERIOD,
            PERIOD_S,
            JACOBI,
            CORRECTED,
            CONVERGED,
            ITERATIONS,
            TOLERANCE,
            MAX_ITERATIONS,
            MONODROMY,
            FLOQUET_REAL,
            FLOQUET_IMAGINARY,
            STABILITY_INDEX,
            STABLE,
            TRAJECTORY,
        }
