impl tbpTransferT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<tbpTransfer<'b>> {
        let KIND = self.KIND;
        let PARKING_ALTITUDE_KM = self.PARKING_ALTITUDE_KM;
        let TARGET_ALTITUDE_KM = self.TARGET_ALTITUDE_KM;
        let INCLINATION_DEG = self.INCLINATION_DEG;
        let TARGET_ORBIT = self.TARGET_ORBIT.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let MAX_ITERATIONS = self.MAX_ITERATIONS;
        let TOLERANCE = self.TOLERANCE;
        let CONVERGED = self.CONVERGED;
        let BURNS = self.BURNS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let TOTAL_DELTA_V_KM_S = self.TOTAL_DELTA_V_KM_S;
        let TIME_OF_FLIGHT_S = self.TIME_OF_FLIGHT_S;
        let TRAJECTORY = self.TRAJECTORY.as_ref().map(|x|{
            x.pack(_fbb)
        });
        tbpTransfer::create(_fbb, &tbpTransferArgs{
            KIND,
            PARKING_ALTITUDE_KM,
            TARGET_ALTITUDE_KM,
            INCLINATION_DEG,
            TARGET_ORBIT,
            MAX_ITERATIONS,
            TOLERANCE,
            CONVERGED,
            BURNS,
            TOTAL_DELTA_V_KM_S,
            TIME_OF_FLIGHT_S,
            TRAJECTORY,
        })
    }
}

