    pub const VT_CYCLES: ::flatbuffers::VOffsetT = 12;
    pub const VT_ANNUAL_DELTA_V_KM_S: ::flatbuffers::VOffsetT = 14;
    pub const VT_MEAN_CYCLE_DELTA_V_KM_S: ::flatbuffers::VOffsetT = 16;
    pub const VT_MAX_CYCLE_DELTA_V_KM_S: ::flatbuffers::VOffsetT = 18;
    pub const VT_CYCLE_DELTA_V_KM_S: ::flatbuffers::VOffsetT = 20;
    pub const VT_BOUNDED: ::flatbuffers::VOffsetT = 22;

