        let NAVIGATION_ERROR_KM = self.NAVIGATION_ERROR_KM();
        let EXECUTION_ERROR_FRACTION = self.EXECUTION_ERROR_FRACTION();
        let CYCLES = self.CYCLES();
        let ANNUAL_DELTA_V_KM_S = self.ANNUAL_DELTA_V_KM_S();
        let MEAN_CYCLE_DELTA_V_KM_S = self.MEAN_CYCLE_DELTA_V_KM_S();
        let MAX_CYCLE_DELTA_V_KM_S = self.MAX_CYCLE_DELTA_V_KM_S();
        let CYCLE_DELTA_V_KM_S = self.CYCLE_DELTA_V_KM_S().map(|x| {
            x.into_iter().collect()
        });
        let BOUNDED = self.BOUNDED();
        tbpStationKeepingT {
            ORBIT,
            STRATEGY,
            NAVIGATION_ERROR_KM,
            EXECUTION_ERROR_FRACTION,
            CYCLES,
            ANNUAL_DELTA_V_KM_S,
            MEAN_CYCLE_DELTA_V_KM_S,
            MAX_CYCLE_DELTA_V_KM_S,
            CYCLE_DELTA_V_KM_S,
            BOUNDED,
        }
