    pub const VT_LIBRATION_POINTS: ::flatbuffers::VOffsetT = 24;
    pub const VT_STATE: ::flatbuffers::VOffsetT = 26;
    pub const VT_JACOBI: ::flatbuffers::VOffsetT = 28;
    pub const VT_ORBITS: ::flatbuffers::VOffsetT = 30;
    pub const VT_TRANSFER: ::flatbuffers::VOffsetT = 32;
