    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args TBPArgs<'args>
    ) -> ::flatbuffers::WIPOffset<TBP<'bldr>> {
        let mut builder = TBPBuilder::new(_fbb);
        builder.add_JACOBI(args.JACOBI);
        builder.add_CREATED_AT_MS(args.CREATED_AT_MS);
        if let Some(x) = args.FRAME_CONVERSION { builder.add_FRAME_CONVERSION(x); }
        if let Some(x) = args.STATION_KEEPING { builder.add_STATION_KEEPING(x); }
        if let Some(x) = args.TRANSFER { builder.add_TRANSFER(x); }
        if let Some(x) = args.ORBITS { builder.add_ORBITS(x); }
        if let Some(x) = args.STATE { builder.add_STATE(x); }
        if let Some(x) = args.LIBRATION_POINTS { builder.add_LIBRATION_POINTS(x); }
        if let Some(x) = args.TRAJECTORY { builder.add_TRAJECTORY(x); }
        if let Some(x) = args.PROPAGATION { builder.add_PROPAGATION(x); }
        if let Some(x) = args.ERROR_MESSAGE { builder.add_ERROR_MESSAGE(x); }
        if let Some(x) = args.ERROR_CODE { builder.add_ERROR_CODE(x); }
        if let Some(x) = args.SYSTEM { builder.add_SYSTEM(x); }
        if let Some(x) = args.PRODUCER { builder.add_PRODUCER(x); }
        if let Some(x) = args.ID { builder.add_ID(x); }
        builder.add_STATUS(args.STATUS);
        builder.add_PROBLEM(args.PROBLEM);
        builder.finish()
    }

