impl TBPT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<TBP<'b>> {
        let ID = self.ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let CREATED_AT_MS = self.CREATED_AT_MS;
        let PRODUCER = self.PRODUCER.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let PROBLEM = self.PROBLEM;
        let SYSTEM = self.SYSTEM.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let STATUS = self.STATUS;
        let ERROR_CODE = self.ERROR_CODE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let ERROR_MESSAGE = self.ERROR_MESSAGE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let PROPAGATION = self.PROPAGATION.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let TRAJECTORY = self.TRAJECTORY.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let LIBRATION_POINTS = self.LIBRATION_POINTS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let STATE = self.STATE.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let JACOBI = self.JACOBI;
        let ORBITS = self.ORBITS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let TRANSFER = self.TRANSFER.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let STATION_KEEPING = self.STATION_KEEPING.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let FRAME_CONVERSION = self.FRAME_CONVERSION.as_ref().map(|x|{
            x.pack(_fbb)
        });
        TBP::create(_fbb, &TBPArgs{
            ID,
            CREATED_AT_MS,
            PRODUCER,
            PROBLEM,
            SYSTEM,
            STATUS,
            ERROR_CODE,
            ERROR_MESSAGE,
            PROPAGATION,
            TRAJECTORY,
            LIBRATION_POINTS,
            STATE,
            JACOBI,
            ORBITS,
            TRANSFER,
            STATION_KEEPING,
            FRAME_CONVERSION,
        })
    }
}

