#[inline]
pub fn tbp_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, TBP_IDENTIFIER, false)
}

#[inline]
pub fn tbp_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, TBP_IDENTIFIER, true)
}

#[inline]
pub fn finish_tbp_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<TBP<'a>>
) {
    fbb.finish(root, Some(TBP_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_tbp_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<TBP<'a>>
) {
    fbb.finish_size_prefixed(root, Some(TBP_IDENTIFIER));
}
